INSERT INTO poses VALUES(1,'Mountain Pose',0.4,'setup','["core", "legs"]',1,'Foundational standing pose for grounding and alignment.','Stand tall with feet hip-width apart, arms at sides. Distribute weight evenly, engage core, lengthen spine.','Use wall support for balance, place block between thighs to engage legs.','mountain_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(2,'Upward Salute',0.25,'main','["shoulders", "core"]',1,'Standing pose with arms raised overhead.','From Mountain Pose, sweep arms overhead, palms facing each other or touching.','Keep hands on hips if shoulders are tight, bend elbows slightly.','upward_salute.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(3,'Forward Fold',0.4,'main','["hamstrings", "back"]',2,'Standing forward bend','Hinge at hips, fold forward with straight spine. Let arms hang or rest on legs.','Bend knees generously, use blocks under hands, hold opposite elbows.','forward_fold.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(4,'Halfway Lift',0.25,'main','["back", "core"]',2,'Partial forward fold with flat back','From forward fold, place hands on shins or fingertips to floor, flatten back.','Hands to thighs or blocks, focus on long spine over depth.','halfway_lift.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(5,'Chaturanga',0.25,'main','["arms", "core"]',3,'Low plank transition pose','From plank, lower down keeping elbows close to body, hover above ground.','Drop knees to ground, use blocks under chest, skip and go to child''s pose.','low_push_up.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(6,'Upward Dog',0.3,'main','["back", "shoulders", "core"]',3,'Backbend with arms supporting body weight','Press hands down, lift chest and thighs off ground, open heart forward.','Keep thighs on ground (cobra variation), use blocks under hands.','upward_dog.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(7,'Downward Dog',0.5,'main','["shoulders", "hamstrings", "core"]',2,'Inverted V-shape, foundational yoga pose','Hands shoulder-width apart, feet hip-width apart, lift hips up and back.','Bend knees, pedal feet, use blocks under hands, forearms down.','downward_dog.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(8,'Chair Pose',0.5,'main','["legs", "core", "glutes"]',2,'Strengthening standing squat pose','Bend knees, sit back as if sitting in chair, arms overhead.','Hands on hips, back against wall, less depth in squat.','chair_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(9,'Warrior I Right',0.75,'right_side','["legs", "core", "shoulders"]',2,'Standing lunge with right foot forward, arms overhead','Step right foot forward, bend right knee over ankle, square hips forward, arms up.','Narrow stance for balance, hands on hips, use wall support.','warrior_i_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(10,'Warrior I Left',0.75,'left_side','["legs", "core", "shoulders"]',2,'Standing lunge with left foot forward, arms overhead','Step left foot forward, bend left knee over ankle, square hips forward, arms up.','Narrow stance for balance, hands on hips, use wall support.','warrior_i_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(11,'Warrior II Right',0.65,'right_side','["legs", "core"]',2,'Standing lunge with right foot forward, arms parallel to ground','Wide stance, bend right knee, arms parallel to floor, gaze over right hand.','Shorter stance, hand on front thigh, use wall behind back leg.','warrior_ii_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(12,'Warrior II Left',0.65,'left_side','["legs", "core"]',2,'Standing lunge with left foot forward, arms parallel to ground','Wide stance, bend left knee, arms parallel to floor, gaze over left hand.','Shorter stance, hand on front thigh, use wall behind back leg.','warrior_ii_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(13,'Warrior III Right',0.75,'right_side','["legs", "core"]',4,'Standing balance on right leg with left leg lifted','Stand on right leg, lift left leg behind, torso forward, arms extended.','Use wall support, hands on hips, keep toe of lifted leg on ground.','warrior_iii_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(14,'Warrior III Left',0.75,'left_side','["legs", "core"]',4,'Standing balance on left leg with right leg lifted','Stand on left leg, lift right leg behind, torso forward, arms extended.','Use wall support, hands on hips, keep toe of lifted leg on ground.','warrior_iii_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(15,'Side Angle Right',0.6,'right_side','["legs", "core", "side_body"]',3,'Side stretch from Warrior II with right foot forward','From Warrior II right, place right hand on thigh or floor, reach left arm over ear.','Hand stays on thigh, use block under bottom hand, take bind under front thigh.','side_angle_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(16,'Side Angle Left',0.6,'left_side','["legs", "core", "side_body"]',3,'Side stretch from Warrior II with left foot forward','From Warrior II left, place left hand on thigh or floor, reach right arm over ear.','Hand stays on thigh, use block under bottom hand, take bind under front thigh.','side_angle_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(17,'Vinyasa Flow',0.5,'transition','["full_body"]',3,'Flowing sequence connecting poses','Flow through plank, low push-up, upward dog, downward dog.','Skip challenging poses, step back/forward instead of jumping.','vinyasa_flow.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(18,'Easy Pose',0.3,'setup','["hips"]',1,'Simple cross-legged sitting position','Sit cross-legged, hands on knees or in lap, spine tall.','Sit on block or blanket, lean against wall, extend legs if uncomfortable.','easy_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(19,'Gentle Neck Rolls',0.3,'preparation','["neck"]',1,'Slow circular movements to warm neck','Slowly roll head in semicircles, avoid full circles, move mindfully.','Just turn head side to side, support head with hand.','gentle_neck_rolls.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(20,'Seated Cat-Cow',0.5,'preparation','["spine", "back"]',1,'Spinal mobility while seated','Arch and round spine while seated, coordinate with breath.','Smaller movements, hand support on knees.','seated_cat_cow.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(21,'Seated Twist Right',1.0,'right_side','["spine", "core"]',2,'Spinal rotation to the right while seated','Sit tall, place right hand behind right hip, left hand on right knee, twist right.','Use chair back for support, smaller range of motion.','seated_twist_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(22,'Seated Twist Left',1.0,'left_side','["spine", "core"]',2,'Spinal rotation to the left while seated','Sit tall, place left hand behind left hip, right hand on left knee, twist left.','Use chair back for support, smaller range of motion.','seated_twist_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(23,'Forward Fold Seated',0.5,'transition','["hamstrings", "back"]',2,'Forward bend from seated position','Hinge at hips, fold forward over legs, keep spine long.','Bend knees, use strap around feet, place pillow on legs.','forward_fold_seated.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(24,'Child''s Pose',0.5,'rest','["hips", "back"]',1,'Restorative kneeling forward fold','Kneel, sit back on heels, fold forward, arms extended or at sides.','Place pillow between calves and thighs, widen knees, use bolster.','childs_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(25,'Table Top',0.25,'setup','["core"]',1,'Neutral hands and knees position','Hands under shoulders, knees under hips, neutral spine.','Place blanket under knees, use blocks under hands if wrists hurt.','table_top.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(26,'Cat-Cow Stretches',0.5,'preparation','["spine", "back"]',1,'Spinal mobility on hands and knees','Alternate between arching (cow) and rounding (cat) the spine.','Smaller movements, move slowly, support knees with blanket.','cat_cow_stretches.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(27,'Low Lunge Right',0.75,'right_side','["hips", "legs"]',2,'Kneeling lunge with right foot forward','Step right foot forward, lower left knee, hands on right thigh or floor.','Place blanket under back knee, use blocks under hands.','low_lunge_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(28,'Low Lunge Left',0.75,'left_side','["hips", "legs"]',2,'Kneeling lunge with left foot forward','Step left foot forward, lower right knee, hands on left thigh or floor.','Place blanket under back knee, use blocks under hands.','low_lunge_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(29,'Lizard Pose Right',1.0,'right_side','["hips", "groin"]',3,'Deep hip opener with right foot forward','From low lunge right, place both hands inside right foot, lower to forearms if possible.','Stay on hands, use blocks under forearms, keep back knee down.','lizard_pose_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(30,'Lizard Pose Left',1.0,'left_side','["hips", "groin"]',3,'Deep hip opener with left foot forward','From low lunge left, place both hands inside left foot, lower to forearms if possible.','Stay on hands, use blocks under forearms, keep back knee down.','lizard_pose_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(31,'Half Pigeon Right',1.25,'right_side','["hips", "glutes"]',3,'Deep hip opener with right knee bent in front','Right knee bent in front, left leg straight back, sit upright or fold forward.','Place block or pillow under right hip, stay upright, use wall support.','half_pigeon_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(32,'Half Pigeon Left',1.25,'left_side','["hips", "glutes"]',3,'Deep hip opener with left knee bent in front','Left knee bent in front, right leg straight back, sit upright or fold forward.','Place block or pillow under left hip, stay upright, use wall support.','half_pigeon_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(33,'Low Cobra',0.5,'main','["back", "shoulders"]',2,'Gentle backbend lying on belly','Lie on belly, hands under shoulders, lift chest using back muscles.','Keep forearms down, very small lift, place pillow under hips.','low_cobra.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(34,'Cobra Pose',0.7,'main','["back", "shoulders", "core"]',3,'Backbend with straight arms','Press hands down, straighten arms, lift chest, keep hips grounded.','Stay on forearms, press hands lightly, use block between thighs.','cobra_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(35,'Camel Pose',1.25,'main','["back", "shoulders", "hips"]',4,'Deep backbend kneeling with hands to heels','Kneel, place hands on heels, lift chest and hips forward.','Hands on lower back, use blocks on calves, tuck toes under.','camel_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(36,'Camel Pose Prep',0.5,'main','["back", "shoulders", "hips"]',3,'Preparation for full camel backbend','Kneel, hands on lower back, lean back gently, open chest.','Hands stay on hips, use wall behind back, place block between thighs.','camel_pose_prep.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(37,'Bridge Pose',1.0,'main','["back", "glutes", "hamstrings"]',2,'Backbend lying on back with knees bent','Lie on back, knees bent, feet flat, lift hips, press feet down.','Place block between thighs, use strap around thighs, support with bolster.','bridge_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(38,'Fish Pose',1.0,'main','["chest", "shoulders", "neck"]',3,'Heart-opening backbend lying on back','Lie on back, hands under glutes, lift chest, crown of head touches floor.','Use bolster under shoulder blades, keep head lifted slightly.','fish_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(39,'Supine Spinal Twist Right',1.0,'right_side','["spine", "hips"]',2,'Lying spinal rotation dropping knees to the right','Lie on back, draw knees to chest, drop both knees to right side.','Place pillow between legs, support knees with bolster.','supine_spinal_twist_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(40,'Supine Spinal Twist Left',1.0,'left_side','["spine", "hips"]',2,'Lying spinal rotation dropping knees to the left','Lie on back, draw knees to chest, drop both knees to left side.','Place pillow between legs, support knees with bolster.','supine_spinal_twist_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(41,'Seated Forward Fold',1.0,'main','["hamstrings", "back"]',2,'Forward bend from seated position with legs extended','Sit with legs extended, hinge at hips, fold forward over legs.','Bend knees, use strap around feet, sit on blanket.','seated_forward_fold.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(42,'Supine Knees to Chest',0.5,'main','["hips", "back"]',1,'Gentle hip release lying on back','Lie on back, hug knees to chest, rock side to side if desired.','Keep one foot on ground, use strap around thighs.','supine_knee_to_chest.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(43,'Happy Baby Pose',0.75,'main','["hips", "groin"]',2,'Playful hip opener lying on back','Lie on back, grab outside edges of feet, knees toward armpits.','Hold behind thighs instead, use strap around feet, rock side to side.','happy_baby_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(44,'Savasana',0.5,'closing','["full_body"]',1,'Final relaxation pose','Lie on back, arms and legs relaxed, close eyes, focus on breath.','Place pillow under knees, blanket over body, bolster under knees.','savasana.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(45,'Wide Legged Forward Fold',0.75,'preparation','["hamstrings", "thighs", "back"]',2,'Forward fold with wide leg stance','Stand with legs wide, hinge at hips, fold forward with hands to floor.','Hands on blocks, bend knees, hands on shins instead of floor.','wide_legged_forward_fold.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(46,'Triangle Pose Right',1.5,'right_side','["legs", "side_body", "core"]',2,'Standing side stretch with right foot forward','Wide stance, right foot forward, reach right hand to ankle/shin, left arm up.','Use block under bottom hand, hand on shin instead of ankle.','triangle_pose_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(47,'Triangle Pose Left',1.5,'left_side','["legs", "side_body", "core"]',2,'Standing side stretch with left foot forward','Wide stance, left foot forward, reach left hand to ankle/shin, right arm up.','Use block under bottom hand, hand on shin instead of ankle.','triangle_pose_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(48,'Revolved Triangle Right',1.0,'right_side','["legs", "spine", "core"]',4,'Twisting triangle with right foot forward','Wide stance, right foot forward, left hand to right foot, right arm up.','Use block under bottom hand, hand on shin, bend front knee.','revolved_triangle_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(49,'Revolved Triangle Left',1.0,'left_side','["legs", "spine", "core"]',4,'Twisting triangle with left foot forward','Wide stance, left foot forward, right hand to left foot, left arm up.','Use block under bottom hand, hand on shin, bend front knee.','revolved_triangle_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(50,'Tree Pose Right',1.0,'right_side','["legs", "core"]',2,'Standing balance on right leg with left foot on inner thigh','Stand on right leg, place left foot on right inner thigh, hands at heart or overhead.','Use wall support, foot on calf instead of thigh, toe on ground for balance.','tree_pose_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(51,'Tree Pose Left',1.0,'left_side','["legs", "core"]',2,'Standing balance on left leg with right foot on inner thigh','Stand on left leg, place right foot on left inner thigh, hands at heart or overhead.','Use wall support, foot on calf instead of thigh, toe on ground for balance.','tree_pose_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(52,'Eagle Pose Right',0.75,'right_side','["legs", "core", "shoulders"]',3,'Eagle pose standing on right leg','Stand on right leg, wrap left leg around, cross arms and bring palms together.','Use wall for balance, keep wrapped toe on ground, just cross arms.','eagle_pose_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(53,'Eagle Pose Left',0.75,'left_side','["legs", "core", "shoulders"]',3,'Eagle pose standing on left leg','Stand on left leg, wrap right leg around, cross arms and bring palms together.','Use wall for balance, keep wrapped toe on ground, just cross arms.','eagle_pose_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(54,'Dancer Pose Right',0.5,'right_side','["legs", "core", "back"]',4,'Dancer pose standing on right leg','Stand on right leg, grab left ankle, kick into hand while leaning forward.','Use wall support, hold with strap, just lift leg without grabbing.','dancer_pose_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(55,'Dancer Pose Left',0.5,'left_side','["legs", "core", "back"]',4,'Dancer pose standing on left leg','Stand on left leg, grab right ankle, kick into hand while leaning forward.','Use wall support, hold with strap, just lift leg without grabbing.','dancer_pose_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(56,'Plank Pose',0.75,'main','["core", "arms", "shoulders"]',3,'Straight arm plank for core strength','Hands under shoulders, body in straight line from head to heels.','Drop knees to ground, forearm plank, hands on elevated surface.','plank_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(57,'Boat Pose',0.75,'main','["core", "hip_flexors"]',3,'V-shaped seated core strengthening pose','Sit, lift legs and lean back, balancing on sitting bones, arms forward.','Bend knees, hands behind thighs, feet on floor.','boat_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(58,'Bicycle Pose',0.5,'main','["core"]',3,'Dynamic core exercise with rotating movement','Lie on back, hands behind head, bicycle legs while twisting torso.','Slower movement, smaller range of motion, hands on chest.','bicycle_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(59,'Side Plank Right',0.5,'right_side','["core", "arms"]',4,'Side plank on right forearm','Lie on right side, prop up on right forearm, lift hips, body in straight line.','Bottom knee on ground, left hand on hip, stay on forearm.','side_plank_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(60,'Side Plank Left',0.5,'left_side','["core", "arms"]',4,'Side plank on left forearm','Lie on left side, prop up on left forearm, lift hips, body in straight line.','Bottom knee on ground, right hand on hip, stay on forearm.','side_plank_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(61,'Hollow Body Hold',0.5,'main','["core", "hip_flexors"]',4,'Isometric core hold with curved spine','Lie on back, press lower back down, lift shoulders and legs.','Bend knees, hands behind head, smaller lift.','hollow_body_hold.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(62,'Crow Pose',0.5,'main','["arms", "core", "wrists"]',4,'Arm balance with knees on upper arms','Squat, hands on floor, lean forward, lift feet, balance on hands.','Keep toes on ground, use block under forehead, practice on higher surface.','crow_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(63,'Side Crow Right',0.75,'right_side','["arms", "core"]',5,'Side crow with twist to the right','Twist right, place hands on floor, hook legs on right arm, lift feet.','Keep one foot on ground, use block under shoulder.','side_crow_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(64,'Side Crow Left',0.75,'left_side','["arms", "core"]',5,'Side crow with twist to the left','Twist left, place hands on floor, hook legs on left arm, lift feet.','Keep one foot on ground, use block under shoulder.','side_crow_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(65,'Butterfly Pose',3.0,'main','["hips", "groin", "thighs"]',1,'Seated hip opener with soles of feet together','Sit with soles of feet together, hold feet, gently draw heels toward pelvis.','Sit on blanket, place blocks under knees, lean against wall.','butterfly_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(66,'Dragon Pose Right',2.5,'right_side','["hips", "hip_flexors"]',2,'Dragon pose with right foot forward','Right foot forward in lunge, slide foot forward, sink hips down.','Place bolster under right thigh, hands on blocks, left knee down.','dragon_pose_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(67,'Dragon Pose Left',2.5,'left_side','["hips", "hip_flexors"]',2,'Dragon pose with left foot forward','Left foot forward in lunge, slide foot forward, sink hips down.','Place bolster under left thigh, hands on blocks, right knee down.','dragon_pose_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(68,'Legs Up Wall',1.5,'closing','["legs"]',1,'Restorative inversion with legs elevated','Lie on back near wall, extend legs up wall, arms relaxed at sides.','Use bolster under lower back, bend knees, eye pillow for relaxation.','legs_up_wall.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(69,'Dolphin Pose',0.75,'preparation','["shoulders", "core", "arms"]',4,'Forearm stand preparation','Forearms on floor, lift hips like downward dog, press forearms down.','Keep head down, use wall for support, bend knees.','dolphin_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(70,'Headstand Prep',1.5,'main','["shoulders", "core", "neck"]',4,'Preparation for full headstand','Forearms down, crown of head on floor, lift hips, walk feet closer.','Practice against wall, keep feet on ground, use blanket under head.','headstand_prep.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(71,'Shoulder Stand',2.0,'main','["shoulders", "core", "neck"]',4,'Supported inversion on shoulders','Lie on back, lift legs overhead, support back with hands.','Use wall for support, legs in easy pose, blanket under shoulders.','shoulder_stand.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(72,'Neck and Shoulder Rolls',0.5,'preparation','["neck", "shoulders"]',1,'Gentle circular movements to release neck and shoulder tension','Slowly roll shoulders backward and forward, then gentle neck side-to-side movements','Support head with hand, smaller movements if any pain','neck_shoulder_rolls.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(73,'Wrist Circles',0.3,'preparation','["wrists", "arms"]',1,'Gentle wrist mobility exercise','Circle wrists slowly in both directions, flex and extend fingers','Smaller circles if wrists are sensitive','wrist_circles.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(74,'Ankle Circles',0.4,'preparation','["ankles"]',1,'Ankle mobility and foot warming','Circle ankles in both directions, point and flex feet','Support leg if balance is challenging','ankle_circles.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(75,'Sphinx Pose',3.0,'main','["back", "spine"]',1,'Gentle yin backbend on forearms','Lie on belly, prop up on forearms, chest open, minimal effort','Place pillow under chest, lower forearms to reduce intensity','sphinx_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(76,'Saddle Pose',4.0,'main','["quadriceps", "hip_flexors", "back"]',3,'Deep yin quad and hip flexor stretch','Kneel and lean back, eventually lying down if comfortable','Stay upright, use bolster behind back, blocks under hands','saddle_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(77,'Caterpillar Pose',4.0,'main','["hamstrings", "back", "spine"]',2,'Yin seated forward fold','Sit with legs extended, round spine forward, let gravity work','Bend knees, sit on blanket, bolster across legs','caterpillar_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(78,'Shoelace Pose Right',4.0,'main','["hips", "glutes"]',2,'Yin hip opener with right leg stacked on top of the left','Stack knees on top of each other, fold forward if comfortable','Sit on blanket, place pillow between legs, stay upright','shoelace_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(79,'Shoelace Pose Left',4.0,'main','["hips", "glutes"]',2,'Yin hip opener with left leg stacked on top of the right','Stack knees on top of each other, fold forward if comfortable','Sit on blanket, place pillow between legs, stay upright','shoelace_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(80,'Reclined Butterfly',3.5,'main','["hips", "groin", "chest"]',1,'Restorative hip opener lying down','Lie back with soles of feet together, arms open wide','Blocks or pillows under knees, bolster under back','reclined_butterfly.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(81,'Twisted Roots Right',3.0,'main','["spine", "hips"]',2,'Yin spinal twist lying down','Lie on back, cross one leg over, let knees fall to one side','Pillow between legs, support knees with bolster','twisted_roots_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(82,'Twisted Roots Left',3.0,'main','["spine", "hips"]',2,'Yin spinal twist lying down','Lie on back, cross one leg over, let knees fall to one side','Pillow between legs, support knees with bolster','twisted_roots_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(83,'Melting Heart',3.5,'main','["shoulders", "chest"]',2,'Yin heart opener on hands and knees','From table top, walk hands forward, melt chest toward floor','Forehead on block, less depth, pillow under chest','melting_heart.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(84,'Gentle Backbend',0.4,'preparation','["back", "chest"]',1,'Mild chest opening movement','Interlace fingers behind back, lift chest, open heart gently','Use strap between hands, smaller movement','gentle_backbend.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(85,'Side Body Stretch Right',0.6,'preparation','["spine"]',1,'Standing lateral stretch','Reach one arm overhead and lean to opposite side','Hand on hip for support, smaller range of motion','side_body_stretch.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(86,'Side Body Stretch Left',0.6,'preparation','["side_body", "spine"]',1,'Standing lateral stretch','Reach one arm overhead and lean to opposite side','Hand on hip for support, smaller range of motion','side_body_stretch.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(87,'High Lunge Right',0.75,'right_side','["legs", "core", "hip_flexors"]',2,'Standing lunge with right foot forward, back knee lifted','Step right foot forward, lift back heel, bend front knee over ankle, arms can be on hips or overhead.','Lower back knee to mat, use blocks under hands for support.','high_lunge_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(88,'High Lunge Left',0.75,'left_side','["legs", "core", "hip_flexors"]',2,'Standing lunge with left foot forward, back knee lifted','Step left foot forward, lift back heel, bend front knee over ankle, arms can be on hips or overhead.','Lower back knee to mat, use blocks under hands for support.','high_lunge_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(89,'Revolved Lunge Right',0.75,'right_side','["legs", "spine", "core"]',4,'Twisted lunge with right foot forward, left hand down','From lunge with right foot forward, place left hand inside right foot, twist right arm up toward ceiling.','Use block under bottom hand, keep back knee down, hand on shin instead of floor.','revolved_lunge_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(90,'Revolved Lunge Left',0.75,'left_side','["legs", "spine", "core"]',4,'Twisted lunge with left foot forward, right hand down','From lunge with left foot forward, place right hand inside left foot, twist left arm up toward ceiling.','Use block under bottom hand, keep back knee down, hand on shin instead of floor.','revolved_lunge_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(91,'Hand to Big Toe Right',0.75,'right_side','["legs", "core"]',4,'Standing balance holding right big toe with right hand','Stand on left leg, bend right knee, grab right big toe with right hand, slowly extend right leg forward.','Use strap around foot, hold knee instead of toe, use wall support.','hand_to_big_toe_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(92,'Hand to Big Toe Left',0.75,'left_side','["legs", "core"]',4,'Standing balance holding left big toe with left hand','Stand on right leg, bend left knee, grab left big toe with left hand, slowly extend left leg forward.','Use strap around foot, hold knee instead of toe, use wall support.','hand_to_big_toe_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(93,'Goddess Pose',0.75,'main','["legs", "glutes", "core"]',2,'Wide-legged squat with arms in goal post position','Stand with legs wide, turn toes out, bend knees, arms in goal posts at shoulder height.','Less depth in squat, hands on hips, back against wall.','goddess_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(94,'Star Pose',0.5,'main','["legs", "core", "shoulders"]',1,'Standing pose with arms and legs wide like a star','Stand with feet wide apart, arms extended wide to sides, palms facing forward.','Narrower stance, arms at shoulder height instead of overhead.','star_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(95,'Pyramid Pose Right',1.0,'right_side','["hamstrings", "legs", "spine"]',3,'Standing forward fold over straight front leg with right foot forward','Step right foot forward, straighten both legs, fold forward over right leg.','Hands on blocks, bend front knee slightly, hands on shin.','pyramid_pose_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(96,'Pyramid Pose Left',1.0,'left_side','["hamstrings", "legs", "spine"]',3,'Standing forward fold over straight front leg with left foot forward','Step left foot forward, straighten both legs, fold forward over left leg.','Hands on blocks, bend front knee slightly, hands on shin.','pyramid_pose_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(97,'Reverse Warrior Right',0.6,'right_side','["legs", "side_body", "shoulders"]',2,'Side bend from Warrior II with right foot forward','From Warrior II right, drop left hand to back leg, reach right arm over head.','Hand stays on thigh, smaller side bend, use wall support.','reverse_warrior_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(98,'Reverse Warrior Left',0.6,'left_side','["legs", "side_body", "shoulders"]',2,'Side bend from Warrior II with left foot forward','From Warrior II left, drop right hand to back leg, reach left arm over head.','Hand stays on thigh, smaller side bend, use wall support.','reverse_warrior_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(99,'Forearm Plank',0.75,'main','["core", "shoulders", "arms"]',3,'Plank pose on forearms instead of hands','Lower to forearms, body in straight line from head to heels.','Drop knees to ground, shorter hold time, use wall.','forearm_plank.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(100,'Compass Pose Right',1.0,'right_side','["hamstrings", "shoulders", "spine"]',5,'Advanced seated pose extending right leg up and to side','Sit with right leg extended up, thread right arm under right leg, left hand holds foot.','Bend extended leg, use strap around foot, stay seated upright.','compass_pose_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(101,'Compass Pose Left',1.0,'left_side','["hamstrings", "shoulders", "spine"]',5,'Advanced seated pose extending left leg up and to side','Sit with left leg extended up, thread left arm under left leg, right hand holds foot.','Bend extended leg, use strap around foot, stay seated upright.','compass_pose_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(102,'Wild Thing Right',0.5,'right_side','["chest", "shoulders", "core"]',4,'Heart-opening transition from side plank','From side plank right, lift top leg, arch back, reach top arm over head.','Keep bottom knee down, smaller backbend, use wall support.','wild_thing_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(103,'Wild Thing Left',0.5,'left_side','["chest", "shoulders", "core"]',4,'Heart-opening transition from side plank','From side plank left, lift top leg, arch back, reach top arm over head.','Keep bottom knee down, smaller backbend, use wall support.','wild_thing_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(104,'Thread Needle Right',0.75,'right_side','["shoulders", "spine", "neck"]',2,'Shoulder and neck release threading right arm under left','From table top, thread right arm under left arm, lower right shoulder to floor.','Stay higher, place pillow under shoulder, use block under head.','thread_needle_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(105,'Thread Needle Left',0.75,'left_side','["shoulders", "spine", "neck"]',2,'Shoulder and neck release threading left arm under right','From table top, thread left arm under right arm, lower left shoulder to floor.','Stay higher, place pillow under shoulder, use block under head.','thread_needle_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(106,'Puppy Pose',1.0,'main','["shoulders", "chest", "spine"]',2,'Heart opener from hands and knees with chest lowered','From table top, walk hands forward, lower chest toward floor, hips over knees.','Forehead on block, less depth, pillow under chest.','puppy_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(107,'Seated Pigeon Right',2.0,'right_side','["hips", "glutes"]',2,'Hip opener sitting in chair or on floor with right ankle on left thigh','Sit and place right ankle on left thigh, gently fold forward if comfortable.','Stay upright, use pillow under right knee, less depth.','seated_pigeon_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(108,'Seated Pigeon Left',2.0,'left_side','["hips", "glutes"]',2,'Hip opener sitting in chair or on floor with left ankle on right thigh','Sit and place left ankle on right thigh, gently fold forward if comfortable.','Stay upright, use pillow under left knee, less depth.','seated_pigeon_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(109,'Garland Pose',1.0,'main','["legs", "hips", "ankles"]',2,'Deep squat with hands at heart center','Feet wider than hips, squat down, palms together at heart, elbows against inner thighs.','Sit on block, hold onto something for balance, place blanket under heels.','garland_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(110,'Twisted Lunge Right',0.75,'right_side','["legs", "spine", "core"]',3,'Lunge with spinal rotation, right foot forward','From lunge right, place left hand on floor, twist right arm to ceiling.','Hand on block, back knee down, smaller twist.','twisted_lunge_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(111,'Twisted Lunge Left',0.75,'left_side','["legs", "spine", "core"]',3,'Lunge with spinal rotation, left foot forward','From lunge left, place right hand on floor, twist left arm to ceiling.','Hand on block, back knee down, smaller twist.','twisted_lunge_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(112,'Cow Face Pose',1.5,'main','["shoulders", "hips"]',3,'Seated pose with crossed legs and arms reaching behind back','Sit with knees stacked, one arm up and one down reaching behind back to clasp hands.','Use strap between hands, sit on blanket, arms don''t need to touch.','cow_face_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(113,'Gate Pose Right',0.75,'right_side','["side_body", "legs"]',2,'Kneeling side stretch with right leg extended to side','Kneel on left knee, extend right leg to side, reach left arm over head toward right.','Hand on extended leg, smaller side bend, use block under right hand.','gate_pose_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(114,'Gate Pose Left',0.75,'left_side','["side_body", "legs"]',2,'Kneeling side stretch with left leg extended to side','Kneel on right knee, extend left leg to side, reach right arm over head toward left.','Hand on extended leg, smaller side bend, use block under left hand.','gate_pose_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(115,'Windshield Wipers',0.75,'main','["hips", "spine"]',1,'Gentle hip and spine mobility lying on back','Lie on back with knees bent, slowly drop knees side to side like windshield wipers.','Smaller range of motion, place hands on knees for control.','windshield_wipers.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(116,'Flying Pigeon Right',0.75,'right_side','["arms", "core", "hips"]',5,'Advanced arm balance with right leg in pigeon position','From crow pose, slide right shin onto left upper arm, extend left leg back.','Keep both feet on ground, use block under forehead, practice crow first.','flying_pigeon_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(117,'Flying Pigeon Left',0.75,'left_side','["arms", "core", "hips"]',5,'Advanced arm balance with left leg in pigeon position','From crow pose, slide left shin onto right upper arm, extend right leg back.','Keep both feet on ground, use block under forehead, practice crow first.','flying_pigeon_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(118,'Eight Angle Pose Right',0.5,'right_side','["arms", "core", "shoulders"]',5,'Advanced arm balance with legs extending to right side','Hook right leg around right arm, extend both legs to right, balance on hands.','Keep feet on ground, use block under hip, practice side crow first.','eight_angle_pose_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(119,'Eight Angle Pose Left',0.5,'left_side','["arms", "core", "shoulders"]',5,'Advanced arm balance with legs extending to left side','Hook left leg around left arm, extend both legs to left, balance on hands.','Keep feet on ground, use block under hip, practice side crow first.','eight_angle_pose_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(120,'Firefly Pose',0.5,'main','["arms", "core", "hamstrings"]',5,'Advanced arm balance with legs extended forward','Squat, hands under thighs, straighten legs forward, balance on hands.','Keep toes on ground, use blocks under hands, bend knees.','firefly_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(121,'Scorpion Pose',1.0,'main','["arms", "back", "core"]',5,'Advanced backbend in forearm stand','From forearm stand, bend knees and arch back to bring feet toward head.','Practice against wall, stay in forearm stand, use spotter.','scorpion_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(122,'Wheel Pose',1.0,'main','["back", "shoulders", "arms"]',4,'Full backbend with hands and feet on ground','Lie on back, hands by ears, press up into full backbend arch.','Stay in bridge, use blocks under hands, practice against wall.','wheel_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(123,'King Pigeon Right',1.5,'right_side','["hips", "back", "shoulders"]',4,'Deep backbend in pigeon pose reaching back foot','From pigeon right, bend back leg, reach back with both hands to grab foot.','Use strap around back foot, stay in regular pigeon, one hand only.','king_pigeon_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(124,'King Pigeon Left',1.5,'left_side','["hips", "back", "shoulders"]',4,'Deep backbend in pigeon pose reaching back foot','From pigeon left, bend back leg, reach back with both hands to grab foot.','Use strap around back foot, stay in regular pigeon, one hand only.','king_pigeon_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(125,'Hollow Body Rocks',0.5,'main','["core", "hip_flexors"]',4,'Dynamic core exercise rocking in hollow body position','In hollow body hold, gently rock forward and back maintaining curved spine.','Rock smaller, bend knees, hands behind head for support.','hollow_body_rocks.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(126,'Russian Twists',0.5,'main','["core", "obliques"]',3,'Seated core exercise twisting side to side','Sit with knees bent, lean back, lift feet, twist torso side to side touching ground.','Keep feet on ground, hands on chest, smaller twists.','russian_twists.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(127,'Bird Dog Right',0.75,'right_side','["core", "back", "glutes"]',2,'Core stability extending right arm and left leg from table top','From table top, extend right arm forward and left leg back, hold steady.','Extend one limb at a time, use wall for hand support, shorter holds.','bird_dog_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(128,'Bird Dog Left',0.75,'left_side','["core", "back", "glutes"]',2,'Core stability extending left arm and right leg from table top','From table top, extend left arm forward and right leg back, hold steady.','Extend one limb at a time, use wall for hand support, shorter holds.','bird_dog_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(129,'Frog Pose',3.0,'main','["hips", "groin", "inner_thighs"]',3,'Deep yin hip opener on forearms with knees wide','From table top, widen knees, lower to forearms, feet in line with knees.','Stay on hands, pillow under knees, less wide stance.','frog_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(130,'Seal Pose',3.0,'main','["back", "shoulders"]',2,'Yin backbend lying on belly with straight arms','Lie on belly, straighten arms completely, lift chest high, minimal effort in back.','Stay on forearms (sphinx), use pillow under hips, bend elbows slightly.','seal_pose.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(131,'Banana Pose Right',3.0,'right_side','["side_body", "spine"]',1,'Yin side body stretch lying on back in curved shape to right','Lie on back, shift hips left, curve body to right like a banana shape.','Arms at sides instead of overhead, pillow under head, smaller curve.','banana_pose_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(132,'Banana Pose Left',3.0,'left_side','["side_body", "spine"]',1,'Yin side body stretch lying on back in curved shape to left','Lie on back, shift hips right, curve body to left like a banana shape.','Arms at sides instead of overhead, pillow under head, smaller curve.','banana_pose_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(133,'Knee to Nose Right',0.5,'right_side','["core", "shoulders", "legs"]',3,'Dynamic downward dog variation bringing right knee toward nose','From downward dog, lift right leg up, exhale draw right knee toward nose, rounding spine.','Keep lifted leg lower, hold pose statically instead of flowing movement.','knee_to_nose_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(134,'Knee to Nose Left',0.5,'left_side','["core", "shoulders", "legs"]',3,'Dynamic downward dog variation bringing left knee toward nose','From downward dog, lift left leg up, exhale draw left knee toward nose, rounding spine.','Keep lifted leg lower, hold pose statically instead of flowing movement.','knee_to_nose_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(135,'Knee to Opposite Elbow Right',0.5,'right_side','["core", "obliques", "shoulders"]',4,'Challenging core twist bringing right knee toward left elbow','From three-legged dog right, draw right knee across body toward left elbow.','Bring knee toward center chest instead of opposite elbow, move slowly.','knee_to_opposite_elbow_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(136,'Knee to Opposite Elbow Left',0.5,'left_side','["core", "obliques", "shoulders"]',4,'Challenging core twist bringing left knee toward right elbow','From three-legged dog left, draw left knee across body toward right elbow.','Bring knee toward center chest instead of opposite elbow, move slowly.','knee_to_opposite_elbow_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(137,'Three Legged Dog Right',0.75,'right_side','["shoulders", "core", "legs", "glutes"]',3,'Downward dog with right leg lifted high','From downward dog, lift right leg straight up behind you, keeping hips square.','Keep lifted leg lower, bend the lifted knee, use wall for hand support.','three_legged_dog_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(138,'Three Legged Dog Left',0.75,'left_side','["shoulders", "core", "legs", "glutes"]',3,'Downward dog with left leg lifted high','From downward dog, lift left leg straight up behind you, keeping hips square.','Keep lifted leg lower, bend the lifted knee, use wall for hand support.','three_legged_dog_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(139,'Downdog Calf Stretch Right',0.75,'right_side','["calves", "hamstrings", "shoulders"]',2,'Downward dog focusing on stretching right calf','From downward dog, step right foot forward slightly, press right heel down firmly.','Bend right knee slightly, use blocks under hands for support.','downdog_calf_stretch_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(140,'Downdog Calf Stretch Left',0.75,'left_side','["calves", "hamstrings", "shoulders"]',2,'Downward dog focusing on stretching left calf','From downward dog, step left foot forward slightly, press left heel down firmly.','Bend left knee slightly, use blocks under hands for support.','downdog_calf_stretch_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(141,'Open Hip Three Leg Downdog Right',0.75,'right_side','["hips", "shoulders", "core"]',4,'Three-legged dog with right hip opened and knee bent','From three-legged dog right, bend right knee and open hip, stacking right hip over left.','Keep leg straighter, don''t lift as high, focus on hip opening.','open_hip_three_leg_downdog_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(142,'Open Hip Three Leg Downdog Left',0.75,'left_side','["hips", "shoulders", "core"]',4,'Three-legged dog with left hip opened and knee bent','From three-legged dog left, bend left knee and open hip, stacking left hip over right.','Keep leg straighter, don''t lift as high, focus on hip opening.','open_hip_three_leg_downdog_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(143,'Humble Warrior Right',1.0,'right_side','["legs", "shoulders", "chest"]',3,'Warrior I with hands clasped behind back, folding forward','From warrior I right, clasp hands behind back, fold forward over right thigh.','Use strap between hands, keep hands on hips, don''t fold as deeply.','humble_warrior_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(144,'Humble Warrior Left',1.0,'left_side','["legs", "shoulders", "chest"]',3,'Warrior I with hands clasped behind back, folding forward','From warrior I left, clasp hands behind back, fold forward over left thigh.','Use strap between hands, keep hands on hips, don''t fold as deeply.','humble_warrior_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(145,'Shiva Squat Right',1.0,'main','["legs", "hips", "glutes"]',3,'The Shiva squat begins from a standing position, shifting your weight onto your left leg. The right leg lifts, and the knee crosses behind the left, mimicking a curtsy. As you bend your standing leg, you sink your hips into a squat.','The Shiva squat is a balancing yoga pose where you stand on one leg, cross the other knee behind the standing knee, and bend both knees while keeping your hips level and core engaged. ','Use yoga blocks or place your hands on the ground at the beginning of the movement. Elevating your hands allows you to maintain proper posture and focus on building strength.','shiva_squat_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(146,'Shiva Squat Left',1.0,'main','["legs", "hips", "glutes"]',3,'The Shiva squat begins from a standing position, shifting your weight onto your right leg. The left leg lifts, and the knee crosses behind the left, mimicking a curtsy. As you bend your standing leg, you sink your hips into a squat.','The Shiva squat is a balancing yoga pose where you stand on one leg, cross the other knee behind the standing knee, and bend both knees while keeping your hips level and core engaged. ','Use yoga blocks or place your hands on the ground at the beginning of the movement. Elevating your hands allows you to maintain proper posture and focus on building strength.','shiva_squat_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(147,'Revolved Hand to Big Toe Right',0.75,'right_side','["legs", "core", "balance"]',5,'Standing balance holding right big toe with left hand in twist','Standing on left leg, hold right big toe with left hand, extend right leg, twist.','Use strap around foot, hold knee instead of toe, use wall support.','revolved_hand_to_big_toe_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(148,'Revolved Hand to Big Toe Left',0.75,'left_side','["legs", "core", "balance"]',5,'Standing balance holding left big toe with right hand in twist','Standing on right leg, hold left big toe with right hand, extend left leg, twist.','Use strap around foot, hold knee instead of toe, use wall support.','revolved_hand_to_big_toe_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(149,'Standing Splits Right',1.0,'main','["hamstrings", "balance", "core"]',3,'Standing forward fold with one leg lifted high behind','From forward fold, lift one leg straight up behind you, hands to floor or leg.','Hands on blocks, don''t lift leg as high, use wall support for balance.','standing_splits_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(150,'Standing Splits Left',1.0,'main','["hamstrings", "balance", "core"]',3,'Standing forward fold with one leg lifted high behind','From forward fold, lift one leg straight up behind you, hands to floor or leg.','Hands on blocks, don''t lift leg as high, use wall support for balance.','standing_splits_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(151,'Half Splits Right',1.5,'main','["hamstrings", "hips"]',2,'Seated forward fold with one leg extended, one leg bent','One leg extended straight, other leg bent with foot against inner thigh, fold forward.','Sit on blanket, use strap around extended foot, keep slight bend in extended knee.','half_splits_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(152,'Half Splits Left',1.5,'main','["hamstrings", "hips"]',2,'Seated forward fold with one leg extended, one leg bent','One leg extended straight, other leg bent with foot against inner thigh, fold forward.','Sit on blanket, use strap around extended foot, keep slight bend in extended knee.','half_splits_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(153,'Seated Gate Right',1.0,'right_side','["side_body", "obliques", "hips"]',2,'Seated side stretch with right leg extended','Seated with right leg straight to side, left leg folded in, side bend over right leg.','Sit on blanket, don''t extend leg as wide, use bottom hand for support.','seated_gate_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(154,'Seated Gate Left',1.0,'left_side','["side_body", "obliques", "hips"]',2,'Seated side stretch with left leg extended','Seated with left leg straight to side, right leg folded in, side bend over left leg.','Sit on blanket, don''t extend leg as wide, use bottom hand for support.','seated_gate_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(155,'Half Frog Right',1.5,'right_side','["quadriceps", "hips"]',4,'Lying prone quad stretch with right leg bent','Lying on stomach, bend right knee, hold right foot with right hand, press down.','Use strap around foot, don''t press foot as close to glutes, use bolster under hips.','half_frog_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(156,'Half Frog Left',1.5,'left_side','["quadriceps", "hips"]',4,'Lying prone quad stretch with left leg bent','Lying on stomach, bend left knee, hold left foot with left hand, press down.','Use strap around foot, don''t press foot as close to glutes, use bolster under hips.','half_frog_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(157,'Side Lunge Right',1.0,'right_side','["legs", "hips", "inner_thighs"]',2,'Wide-legged lunge to the right side','Wide stance, bend right knee deeply, keep left leg straight, hands to floor or thigh.','Don''t lunge as deeply, use blocks under hands, hold onto chair.','side_lunge_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(158,'Side Lunge Left',1.0,'left_side','["legs", "hips", "inner_thighs"]',2,'Wide-legged lunge to the left side','Wide stance, bend left knee deeply, keep right leg straight, hands to floor or thigh.','Don''t lunge as deeply, use blocks under hands, hold onto chair.','side_lunge_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(159,'Head to Knee Right',1.5,'right_side','["hamstrings", "spine"]',2,'Seated forward fold with right leg extended','Right leg straight, left foot to inner right thigh, fold forward over right leg.','Sit on blanket, use strap around foot, keep slight bend in extended leg.','head_to_knee_right.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(160,'Head to Knee Left',1.5,'left_side','["hamstrings", "spine"]',2,'Seated forward fold with left leg extended','Left leg straight, right foot to inner left thigh, fold forward over left leg.','Sit on blanket, use strap around foot, keep slight bend in extended leg.','head_to_knee_left.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
INSERT INTO poses VALUES(161,'Bow',0.75,'main','["back", "chest", "quadriceps"]',4,'Backbend lying on stomach holding both feet','Lying on stomach, bend both knees, grab ankles, lift chest and thighs off floor.','Hold one foot at a time, use strap around feet, rock gently side to side.','bow.png','2025-08-28 17:42:40','2025-08-28 17:42:40');
