PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE poses (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT UNIQUE NOT NULL,
                default_duration REAL NOT NULL,
                type TEXT NOT NULL,
                muscle_groups TEXT NOT NULL,  -- JSON array as string
                difficulty INTEGER NOT NULL,
                description TEXT,
                instructions TEXT,
                modifications TEXT,
                image_filename TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE flows (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT UNIQUE NOT NULL,
                duration REAL NOT NULL,
                category TEXT,
                style TEXT,  -- JSON array as string
                muscle_groups TEXT,  -- JSON array as string  
                difficulty INTEGER,
                energy_level TEXT,
                tags TEXT,  -- JSON array as string
                flow_data TEXT NOT NULL,  -- JSON string of the flow
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE sequences (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT UNIQUE NOT NULL,
                total_duration REAL NOT NULL,
                style TEXT,
                muscle_groups TEXT,  -- JSON array as string
                sequence_data TEXT NOT NULL,  -- JSON string of the sequence
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE favorites (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                type TEXT NOT NULL,  -- 'pose', 'flow', 'sequence'
                reference_id INTEGER,  -- ID of the favorited item
                favorite_data TEXT,  -- JSON string for complex favorites
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE practice_sessions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                session_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                sequence_name TEXT,
                duration_minutes REAL,
                rating INTEGER,  -- 1-5 stars
                notes TEXT,
                sequence_data TEXT  -- JSON string of what was practiced
            );
CREATE TABLE class_templates (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    style_name TEXT UNIQUE NOT NULL,
                    warm_up_percentage REAL,
                    main_flow_percentage REAL,
                    cool_down_percentage REAL,
                    energy_progression TEXT,
                    max_difficulty_jump INTEGER,
                    requires_counter_poses BOOLEAN,
                    flow_style TEXT,
                    typical_peak_difficulty INTEGER,
                    min_flows INTEGER,
                    max_flows INTEGER,
                    time_tolerance REAL,
                    template_data TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE muscle_groups (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT UNIQUE NOT NULL
            );
CREATE TABLE yoga_styles (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT UNIQUE NOT NULL
            );
CREATE TABLE pose_muscle_groups (
                pose_id INTEGER REFERENCES poses(id) ON DELETE CASCADE,
                muscle_group_id INTEGER REFERENCES muscle_groups(id) ON DELETE CASCADE,
                PRIMARY KEY (pose_id, muscle_group_id)
            );
CREATE TABLE flow_poses (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                flow_id INTEGER REFERENCES flows(id) ON DELETE CASCADE,
                pose_id INTEGER REFERENCES poses(id) ON DELETE CASCADE,
                sequence_order INTEGER NOT NULL,
                pose_duration REAL,
                UNIQUE(flow_id, sequence_order)
            );
CREATE TABLE flow_styles (
                flow_id INTEGER REFERENCES flows(id) ON DELETE CASCADE,
                style_id INTEGER REFERENCES yoga_styles(id) ON DELETE CASCADE,
                PRIMARY KEY (flow_id, style_id)
            );
CREATE TABLE flow_muscle_groups (
                flow_id INTEGER REFERENCES flows(id) ON DELETE CASCADE,
                muscle_group_id INTEGER REFERENCES muscle_groups(id) ON DELETE CASCADE,
                PRIMARY KEY (flow_id, muscle_group_id)
            );
CREATE TABLE sequence_flows (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                sequence_id INTEGER REFERENCES sequences(id) ON DELETE CASCADE,
                flow_id INTEGER REFERENCES flows(id) ON DELETE CASCADE,
                section_type TEXT NOT NULL,
                sequence_order INTEGER NOT NULL,
                UNIQUE(sequence_id, section_type, sequence_order)
            );
CREATE TABLE sequence_muscle_groups (
                sequence_id INTEGER REFERENCES sequences(id) ON DELETE CASCADE,
                muscle_group_id INTEGER REFERENCES muscle_groups(id) ON DELETE CASCADE,
                PRIMARY KEY (sequence_id, muscle_group_id)
            );
CREATE TABLE sequence_styles (
                sequence_id INTEGER REFERENCES sequences(id) ON DELETE CASCADE,
                style_id INTEGER REFERENCES yoga_styles(id) ON DELETE CASCADE,
                PRIMARY KEY (sequence_id, style_id)
            );
CREATE TABLE favorite_poses (
                favorite_id INTEGER REFERENCES favorites(id) ON DELETE CASCADE,
                pose_id INTEGER REFERENCES poses(id) ON DELETE CASCADE,
                PRIMARY KEY (favorite_id, pose_id)
            );
CREATE TABLE favorite_flows (
                favorite_id INTEGER REFERENCES favorites(id) ON DELETE CASCADE,
                flow_id INTEGER REFERENCES flows(id) ON DELETE CASCADE,
                PRIMARY KEY (favorite_id, flow_id)
            );
CREATE TABLE favorite_sequences (
                favorite_id INTEGER REFERENCES favorites(id) ON DELETE CASCADE,
                sequence_id INTEGER REFERENCES sequences(id) ON DELETE CASCADE,
                PRIMARY KEY (favorite_id, sequence_id)
            );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_poses_name ON poses(name);
CREATE INDEX idx_poses_difficulty ON poses(difficulty);
CREATE INDEX idx_flows_name ON flows(name);
CREATE INDEX idx_flows_difficulty ON flows(difficulty);
CREATE INDEX idx_favorites_type ON favorites(type);
CREATE INDEX idx_sequences_name ON sequences(name);
CREATE INDEX idx_flow_poses_order ON flow_poses(flow_id, sequence_order);
CREATE INDEX idx_sequence_flows_order ON sequence_flows(sequence_id, section_type, sequence_order);
COMMIT;
